        self.node_logs[leader_id].append(entry)
        return entry

    def replicate_to_follower(self, follower_id: int, entry: LogEntry, prev_term: int, prev_idx: int) -> bool:
        f_log = self.node_logs[follower_id]
        # Log matching property check
        if prev_idx > 0:
            if len(f_log) < prev_idx or f_log[prev_idx - 1].term != prev_term:
                return False  # Inconsistency detected
        # Overwrite conflicting entries and append
        del f_log[prev_idx:]
        f_log.append(entry)
        return True

    def check_majority_committed(self, entry_index: int, entry_term: int) -> bool:
